

/* ── 梅花易數 ── */
const MH=(function(){
// meihua_full_analysis.js (修正版)
//
// 簡化版梅花易數完整分析器
//
// 本程式包含：
// 1. 數字起上卦、下卦
// 2. 動爻計算
// 3. 本卦、互卦、變卦
// 4. 體卦、用卦判斷
// 5. 體用五行生剋
// 6. 季節旺衰（需要提供 season）
// 7. 變卦影響：動爻變後，體卦與「變卦用卦」的關係
// 8. 互卦影響：互卦上下兩卦與體卦的關係
// 9. 變卦趨勢
// 10. 簡化的綜合吉凶參考
//
// 修正紀錄：
// - 移除舊版「動爻影響」：動爻所在卦必定是用卦，舊版等於把「用 vs 體」重複計分，
//   且 relationToUse 永遠是「比和」。改為「體 vs 變卦用卦」。
// - 旺衰調整改為依體用關係決定正負號，不再一律「體分 − 用分」。
// - 互卦納入評分。
// - 修正「四季末季」的描述字串。
// - 範例只在直接執行檔案時才跑，被 require 時不會輸出。
// - 數字檢查改用 Number.isSafeInteger，避免超大數取餘失準。
//
// 注意：
// - 梅花易數有不同流派，體用、旺衰、應期的細節可能不同。
// - 本程式是可重現的規則化參考模型，不代表唯一正統解法。
// - 若沒有提供占問時間，就不能嚴謹判定月令旺衰；本程式會標示為「未提供」。

const TRIGRAMS = {
  1: { name: '乾', nature: '天', element: '金', lines: [1, 1, 1] },
  2: { name: '兌', nature: '澤', element: '金', lines: [1, 1, 0] },
  3: { name: '離', nature: '火', element: '火', lines: [1, 0, 1] },
  4: { name: '震', nature: '雷', element: '木', lines: [1, 0, 0] },
  5: { name: '巽', nature: '風', element: '木', lines: [0, 1, 1] },
  6: { name: '坎', nature: '水', element: '水', lines: [0, 1, 0] },
  7: { name: '艮', nature: '山', element: '土', lines: [0, 0, 1] },
  8: { name: '坤', nature: '地', element: '土', lines: [0, 0, 0] },
};

const HEXAGRAMS = {
  '11': '乾為天', '12': '天澤履', '13': '天火同人', '14': '天雷無妄',
  '15': '天風姤', '16': '天水訟', '17': '天山遯', '18': '天地否',
  '21': '澤天夬', '22': '兌為澤', '23': '澤火革', '24': '澤雷隨',
  '25': '澤風大過', '26': '澤水困', '27': '澤山咸', '28': '澤地萃',
  '31': '火天大有', '32': '火澤睽', '33': '離為火', '34': '火雷噬嗑',
  '35': '火風鼎', '36': '火水未濟', '37': '火山旅', '38': '火地晉',
  '41': '雷天大壯', '42': '雷澤歸妹', '43': '雷火豐', '44': '震為雷',
  '45': '雷風恆', '46': '雷水解', '47': '雷山小過', '48': '雷地豫',
  '51': '風天小畜', '52': '風澤中孚', '53': '風火家人', '54': '風雷益',
  '55': '巽為風', '56': '風水渙', '57': '風山漸', '58': '風地觀',
  '61': '水天需', '62': '水澤節', '63': '水火既濟', '64': '水雷屯',
  '65': '水風井', '66': '坎為水', '67': '水山蹇', '68': '水地比',
  '71': '山天大畜', '72': '山澤損', '73': '山火賁', '74': '山雷頤',
  '75': '山風蠱', '76': '山水蒙', '77': '艮為山', '78': '山地剝',
  '81': '地天泰', '82': '地澤臨', '83': '地火明夷', '84': '地雷復',
  '85': '地風升', '86': '地水師', '87': '地山謙', '88': '坤為地',
};

// key 生 value
const GENERATES = {
  木: '火',
  火: '土',
  土: '金',
  金: '水',
  水: '木',
};

// key 剋 value
const CONTROLS = {
  木: '土',
  土: '水',
  水: '火',
  火: '金',
  金: '木',
};

// 這裡採用常見的季節旺衰簡化表。
// 「旺、相、休、囚、死」是相對強弱，不是絕對吉凶。
const SEASON_STRENGTH = {
  春: { 木: '旺', 火: '相', 水: '休', 金: '囚', 土: '死' },
  夏: { 火: '旺', 土: '相', 木: '休', 水: '囚', 金: '死' },
  秋: { 金: '旺', 水: '相', 土: '休', 火: '囚', 木: '死' },
  冬: { 水: '旺', 木: '相', 金: '休', 土: '囚', 火: '死' },
  四季末: { 土: '旺', 金: '相', 火: '休', 木: '囚', 水: '死' },
};

const STRENGTH_SCORE = {
  旺: 4,
  相: 3,
  休: 2,
  囚: 1,
  死: 0,
};

// 旺衰分數以「休」(2) 為中點，轉成 -2 ~ +2 的偏移量。
const STRENGTH_CENTER = 2;

// 用卦旺衰對吉凶的方向：
// 用生體：用越旺，助力越大（+）
// 用剋體：用越旺，壓力越大（−）
// 體剋用：用越旺，越難掌控（−）
// 體生用：用越旺，耗洩越多（−）
// 比和：不調整
const USE_STRENGTH_SIGN = {
  用生體: 1,
  用剋體: -1,
  體剋用: -1,
  體生用: -1,
  比和: 0,
};

const VALID_ELEMENTS = new Set(['木', '火', '土', '金', '水']);
const VALID_SEASONS = new Set(Object.keys(SEASON_STRENGTH));

function validatePositiveInteger(value, name) {
  if (!Number.isSafeInteger(value) || value <= 0) {
    throw new TypeError(`${name} 必須是正整數（且不可超過 ${Number.MAX_SAFE_INTEGER}）。`);
  }
}

function modToTrigramNumber(value) {
  return value % 8 === 0 ? 8 : value % 8;
}

function modToMovingLine(value) {
  return value % 6 === 0 ? 6 : value % 6;
}

function getHexagramName(upperNumber, lowerNumber) {
  const key = `${upperNumber}${lowerNumber}`;
  if (!HEXAGRAMS[key]) {
    throw new Error(`找不到六十四卦資料：${key}`);
  }
  return HEXAGRAMS[key];
}

function linesToTrigramNumber(lines) {
  if (!Array.isArray(lines) || lines.length !== 3) {
    throw new Error('八卦爻線必須是長度為 3 的陣列。');
  }

  const entry = Object.entries(TRIGRAMS).find(([, trigram]) => {
    return trigram.lines.join('') === lines.join('');
  });

  if (!entry) {
    throw new Error(`找不到八卦爻線：${lines.join('')}`);
  }

  return Number(entry[0]);
}

function getRelation(bodyElement, useElement) {
  if (!VALID_ELEMENTS.has(bodyElement) || !VALID_ELEMENTS.has(useElement)) {
    throw new Error(`無效的五行：體=${bodyElement}，用=${useElement}`);
  }

  if (bodyElement === useElement) {
    return {
      type: '比和',
      basicScore: 1,
      description: '體用同氣，通常代表平穩、協調。',
    };
  }

  if (GENERATES[useElement] === bodyElement) {
    return {
      type: '用生體',
      basicScore: 3,
      description: '用卦生體卦，通常代表外部助力、資源或對方對自己有利。',
    };
  }

  if (GENERATES[bodyElement] === useElement) {
    return {
      type: '體生用',
      basicScore: -1,
      description: '體卦生用卦，通常代表自己付出較多、能量或資源向外流失。',
    };
  }

  if (CONTROLS[bodyElement] === useElement) {
    return {
      type: '體剋用',
      basicScore: 2,
      description: '體卦剋用卦，通常代表自己有掌控力，但往往需要努力、競爭或付出。',
    };
  }

  if (CONTROLS[useElement] === bodyElement) {
    return {
      type: '用剋體',
      basicScore: -3,
      description: '用卦剋體卦，通常代表外在壓力、阻礙或對手力量較強。',
    };
  }

  throw new Error(`無法判斷五行關係：體=${bodyElement}，用=${useElement}`);
}

function getSeasonStrength(element, season) {
  if (!season) {
    return {
      season: null,
      status: '未提供',
      score: null,
      description: '未提供占問時間，暫不判斷月令旺衰。',
    };
  }

  if (!VALID_SEASONS.has(season)) {
    throw new Error(`season 必須是：${[...VALID_SEASONS].join('、')}。`);
  }

  const status = SEASON_STRENGTH[season][element];
  const seasonLabel = season === '四季末' ? season : `${season}季`;
  return {
    season,
    status,
    score: STRENGTH_SCORE[status],
    description: `${seasonLabel}${element}屬於「${status}」。`,
  };
}

// 旺衰調整：體旺為吉；用卦旺衰的方向依體用關係而定。
function getStrengthAdjustment(relation, bodyStrength, useStrength) {
  if (bodyStrength.score === null || useStrength.score === null) {
    return {
      score: 0,
      description: '未提供季節，不做旺衰調整。',
    };
  }

  const bodyShift = bodyStrength.score - STRENGTH_CENTER;
  const useShift =
    (useStrength.score - STRENGTH_CENTER) * USE_STRENGTH_SIGN[relation.type];
  // 避免產生 -0
  const score = bodyShift + useShift + 0;

  return {
    score,
    description:
      `體卦${bodyStrength.status}（${bodyShift >= 0 ? '+' : ''}${bodyShift}），` +
      `用卦${useStrength.status}（${useShift >= 0 ? '+' : ''}${useShift}，依「${relation.type}」判斷方向）。`,
  };
}

// 動爻變後的影響：只有動爻所在的卦（用卦）會改變，
// 因此看「體卦」與「變卦用卦」的新關係，代表事情發展後的結果傾向。
function getChangeEffect(movingLine, body, use, changedUse) {
  const changedRelation = getRelation(body.element, changedUse.element);
  const useElementChanged = use.element !== changedUse.element;

  return {
    line: movingLine,
    movingSide: movingLine >= 4 ? '上卦' : '下卦',
    useGua: use.name,
    useElement: use.element,
    changedUseGua: changedUse.name,
    changedUseElement: changedUse.element,
    useElementChanged,
    relationType: changedRelation.type,
    score: changedRelation.basicScore,
    description:
      `動爻變後，用卦由「${use.name}（${use.element}）」變為「${changedUse.name}（${changedUse.element}）」，` +
      `與體卦成「${changedRelation.type}」。${changedRelation.description}`,
  };
}

// 互卦的影響：互卦上下兩卦與體卦的關係（互卦代表事情的過程、內在因素）。
// 每個互卦：生體 +1、體剋 +1、比和 0、體生 −1、剋體 −1，合計 −2 ~ +2。
function getHuEffect(body, huUpper, huLower) {
  const scoreOf = (trigram) => {
    const relation = getRelation(body.element, trigram.element);
    const score = { 用生體: 1, 體剋用: 1, 比和: 0, 體生用: -1, 用剋體: -1 }[relation.type];
    return {
      trigram: trigram.name,
      element: trigram.element,
      relationType: relation.type,
      score,
    };
  };

  const upper = scoreOf(huUpper);
  const lower = scoreOf(huLower);
  const total = upper.score + lower.score;

  return {
    upper,
    lower,
    score: total,
    description:
      `互卦上卦「${upper.trigram}」與體為「${upper.relationType}」，` +
      `互卦下卦「${lower.trigram}」與體為「${lower.relationType}」，` +
      `代表過程中的助力與阻力${total > 0 ? '偏順' : total < 0 ? '偏逆' : '大致相當'}。`,
  };
}

function getTrend(benGua, huGua, bianGua, relation, changeEffect) {
  let description;
  if (relation.type === changeEffect.relationType) {
    description = `本卦與變卦的體用主關係都為「${relation.type}」，整體方向較一致。`;
  } else {
    description = `本卦為「${relation.type}」，變卦轉為「${changeEffect.relationType}」，後續局勢可能出現轉折。`;
  }

  return {
    benGua,
    huGua,
    bianGua,
    changedRelationType: changeEffect.relationType,
    description,
  };
}

// 分數範圍約 −12 ~ +12：體用 ±3、變卦 ±3、互卦 ±2、旺衰 ±4。
function getOverallJudgement(totalScore) {
  if (totalScore >= 6) {
    return {
      level: '偏吉',
      description: '助力較多，事情成功條件較佳，但仍需配合實際行動。',
    };
  }
  if (totalScore >= 3) {
    return {
      level: '小吉',
      description: '有可成之象，但可能需要努力、等待或處理細節。',
    };
  }
  if (totalScore >= -2) {
    return {
      level: '平',
      description: '吉凶力量接近，結果取決於執行、時機與具體環境。',
    };
  }
  if (totalScore >= -5) {
    return {
      level: '小凶',
      description: '阻力或消耗偏多，宜保守處理並降低預期。',
    };
  }
  return {
    level: '偏凶',
    description: '外在阻力較強，應先處理風險，不宜貿然推進。',
  };
}

function castHexagram(num1, num2, options = {}) {
  validatePositiveInteger(num1, 'num1');
  validatePositiveInteger(num2, 'num2');

  const { season = null } = options;

  const upperNumber = modToTrigramNumber(num1);
  const lowerNumber = modToTrigramNumber(num2);
  const movingTotal = options.movingTotal != null ? options.movingTotal : num1 + num2;
  const movingLine = modToMovingLine(movingTotal);

  const upper = TRIGRAMS[upperNumber];
  const lower = TRIGRAMS[lowerNumber];
  // 爻線由下往上：初爻、二爻、三爻（下卦），四爻、五爻、上爻（上卦）
  const originalLines = [...lower.lines, ...upper.lines];

  const benGua = getHexagramName(upperNumber, lowerNumber);

  // 互卦：二、三、四爻為下互卦；三、四、五爻為上互卦。
  const huLowerNumber = linesToTrigramNumber(originalLines.slice(1, 4));
  const huUpperNumber = linesToTrigramNumber(originalLines.slice(2, 5));
  const huGua = getHexagramName(huUpperNumber, huLowerNumber);
  const huUpper = TRIGRAMS[huUpperNumber];
  const huLower = TRIGRAMS[huLowerNumber];

  // 變卦：動爻陰陽互換。
  const changedLines = [...originalLines];
  changedLines[movingLine - 1] = changedLines[movingLine - 1] === 1 ? 0 : 1;
  const bianLowerNumber = linesToTrigramNumber(changedLines.slice(0, 3));
  const bianUpperNumber = linesToTrigramNumber(changedLines.slice(3, 6));
  const bianGua = getHexagramName(bianUpperNumber, bianLowerNumber);
  const changedUpper = TRIGRAMS[bianUpperNumber];
  const changedLower = TRIGRAMS[bianLowerNumber];

  // 動爻在上卦：上卦為用、下卦為體；動爻在下卦：下卦為用、上卦為體。
  const isUpperMoving = movingLine >= 4;
  const body = isUpperMoving ? lower : upper;
  const use = isUpperMoving ? upper : lower;
  // 只有動爻所在的卦會改變，體卦在變卦中不變。
  const changedUse = isUpperMoving ? changedUpper : changedLower;

  const relation = getRelation(body.element, use.element);
  const bodyStrength = getSeasonStrength(body.element, season);
  const useStrength = getSeasonStrength(use.element, season);
  const changeEffect = getChangeEffect(movingLine, body, use, changedUse);
  const huEffect = getHuEffect(body, huUpper, huLower);
  const strengthAdjustment = getStrengthAdjustment(relation, bodyStrength, useStrength);

  // 綜合分數是規則化參考，不是傳統流派唯一標準。
  const totalScore =
    relation.basicScore +
    changeEffect.score +
    huEffect.score +
    strengthAdjustment.score;

  const trend = getTrend(benGua, huGua, bianGua, relation, changeEffect);
  const overall = getOverallJudgement(totalScore);

  return {
    input: { num1, num2 },
    calculation: {
      upperRemainder: num1 % 8,
      lowerRemainder: num2 % 8,
      sum: num1 + num2,
      movingTotal,
      movingLineRemainder: movingTotal % 6,
    },
    movingLine,
    upperGua: upper.name,
    upperNature: upper.nature,
    upperElement: upper.element,
    lowerGua: lower.name,
    lowerNature: lower.nature,
    lowerElement: lower.element,
    originalLines,
    benGua,
    huGua,
    huUpperGua: huUpper.name,
    huUpperElement: huUpper.element,
    huLowerGua: huLower.name,
    huLowerElement: huLower.element,
    changedLines,
    bianGua,
    bianUpperGua: changedUpper.name,
    bianUpperElement: changedUpper.element,
    bianLowerGua: changedLower.name,
    bianLowerElement: changedLower.element,
    bodyGua: body.name,
    bodyElement: body.element,
    bodySide: isUpperMoving ? '下卦' : '上卦',
    useGua: use.name,
    useElement: use.element,
    useSide: isUpperMoving ? '上卦' : '下卦',
    relationType: relation.type,
    relationDescription: relation.description,
    season: season || '未提供',
    bodyStrength,
    useStrength,
    strengthAdjustment,
    changeEffect,
    huEffect,
    trend,
    score: {
      relation: relation.basicScore,
      change: changeEffect.score,
      hu: huEffect.score,
      strengthAdjustment: strengthAdjustment.score,
      total: totalScore,
    },
    overall,
  };
}


return{castHexagram,TRIGRAMS}})();
const MH_TXT=["元亨利貞。|初九：潛龍，勿用。|九二：見龍在田，利見大人。|九三：君子終日乾乾，夕惕若，厲，無咎。|九四：或躍在淵，無咎。|九五：飛龍在天，利見大人。|上九：亢龍有悔。|用九：見群龍無首，吉。|剛健自強|大吉亨通之象，像龍一步步成長：先潛伏、再出現、再奮進、再騰飛，到頂點要防過頭。凡事宜自強不息、循序而進，位高時更要謙退。", "元，亨，利牝馬之貞。君子有攸往，先迷後得主，利。西南得朋，東北喪朋。安貞，吉。|初六：履霜，堅冰至。|六二：直、方、大，不習無不利。|六三：含章可貞，或從王事，無成有終。|六四：括囊，無咎無譽。|六五：黃裳，元吉。|上六：龍戰于野，其血玄黃。|用六：利永貞。|柔順承載|以柔順厚德承載萬物，宜跟隨、配合而不爭先，先觀察、後行動，安守本分可得吉；到了極處，柔也會引發衝突，要知道收斂。", "元亨利貞，勿用有攸往，利建侯。|初九：磐桓，利居貞，利建侯。|六二：屯如邅如，乘馬班如。匪寇婚媾，女子貞不字，十年乃字。|六三：即鹿無虞，惟入于林中，君子幾不如舍，往吝。|六四：乘馬班如，求婚媾，往吉，無不利。|九五：屯其膏，小貞吉，大貞凶。|上六：乘馬班如，泣血漣如。||起步維艱|萬事開頭難，像草木剛破土，充滿阻礙卻也蘊含生機。不宜急著大動作，先穩住根基、尋找盟友與幫手，慢慢累積就能打開局面。", "亨。匪我求童蒙，童蒙求我。初筮告，再三瀆，瀆則不告。利貞。|初六：發蒙，利用刑人，用說桎梏，以往吝。|九二：包蒙吉；納婦吉；子克家。|六三：勿用取女，見金夫，不有躬，無攸利。|六四：困蒙，吝。|六五：童蒙，吉。|上九：擊蒙，不利為寇，利禦寇。||啟蒙求教|眼前還處在懵懂不明的階段，需要虛心求教、接受引導。態度要誠懇，不能反覆質疑；學習和釐清之後，方向自然明朗。", "有孚，光亨，貞吉。利涉大川。|初九：需于郊，利用恆，無咎。|九二：需于沙，小有言，終吉。|九三：需于泥，致寇至。|六四：需于血，出自穴。|九五：需于酒食，貞吉。|上六：入于穴，有不速之客三人來，敬之終吉。||耐心等待|時機未到，需要等待。保持誠信與耐心、做好準備，不要躁進；越接近目標越要謹慎，等到條件成熟自然順利。", "有孚，窒。惕中吉，終凶。利見大人，不利涉大川。|初六：不永所事，小有言，終吉。|九二：不克訟，歸而逋，其邑人三百戶，無眚。|六三：食舊德，貞厲，終吉。或從王事，無成。|九四：不克訟，復即命渝，安貞吉。|九五：訟元吉。|上九：或錫之鞶帶，終朝三褫之。||爭訟糾紛|有爭執、矛盾或官司之象。即使有理也要戒慎，爭到底往往兩敗，適度退讓、請公正的人居中調解才是上策。", "貞，丈人，吉，無咎。|初六：師出以律，否臧凶。|九二：在師中，吉，無咎，王三錫命。|六三：師或輿尸，凶。|六四：師左次，無咎。|六五：田有禽，利執言，無咎。長子帥師，弟子輿尸，貞凶。|上六：大君有命，開國承家，小人勿用。||統帥出師|像帶領隊伍作戰，重在紀律與正確的領導人。出動前要名正言順、行事有規矩、用對的人；若指揮不當或用人不當就會吃虧。", "吉。原筮元永貞，無咎。不寧方來，後夫凶。|初六：有孚比之，無咎。有孚盈缶，終來有它吉。|六二：比之自內，貞吉。|六三：比之匪人。|六四：外比之，貞吉。|九五：顯比，王用三驅，失前禽，邑人不誡，吉。|上六：比之無首，凶。||親近依附|彼此親附、團結合作之象。要以誠信選擇可靠的人相親相輔，及早靠攏較吉，猶豫拖延或所託非人就不好。", "亨。密雲不雨，自我西郊。|初九：復自道，何其咎？吉。|九二：牽復，吉。|九三：輿說輻，夫妻反目。|六四：有孚，血去惕出，無咎。|九五：有孚攣如，富以其鄰。|上九：既雨既處，尚德載，婦貞厲。月幾望，君子征凶。||小有積蓄|力量還小，只能小幅度累積與牽制，像烏雲密佈卻還沒下雨。宜以柔克剛、耐心積蓄，不宜強行躁進，到下雨時自會水到渠成。", "履虎尾，不咥人，亨。|初九：素履，往無咎。|九二：履道坦坦，幽人貞吉。|六三：眇能視，跛能履，履虎尾，咥人，凶。武人為于大君。|九四：履虎尾，愬愬，終吉。|九五：夬履，貞厲。|上九：視履考祥，其旋元吉。||謹慎行事|像踩在老虎尾巴後面行走，處境有風險，但只要守禮、小心、態度謙和，反而能平安通過。切忌逞強冒進。", "小往大來，吉，亨。|初九：拔茅茹，以其彙，征吉。|九二：包荒，用馮河，不遐遺，朋亡，得尚于中行。|九三：無平不陂，無往不復，艱貞無咎。勿恤其孚，于食有福。|六四：翩翩，不富以其鄰，不戒以孚。|六五：帝乙歸妹，以祉元吉。|上六：城復于隍，勿用師，自邑告命，貞吝。||天地交泰|上下相通、陰陽調和，是順利亨通的好時機。但「泰極否來」，順境中要居安思危、不能鬆懈，否則局面會逆轉。", "否之匪人，不利君子貞，大往小來。|初六：拔茅茹，以其彙，貞吉亨。|六二：包承，小人吉，大人否亨。|六三：包羞。|九四：有命無咎，疇離祉。|九五：休否，大人吉。其亡其亡，繫于苞桑。|上九：傾否，先否後喜。||閉塞不通|上下不通、小人當道的閉塞時期，不宜強出頭。守住正道、低調自保、保持警惕，等到轉機出現，閉塞終會被打開。", "同人于野，亨。利涉大川，利君子貞。|初九：同人于門，無咎。|六二：同人于宗，吝。|九三：伏戎于莽，升其高陵，三歲不興。|九四：乘其墉，弗克攻，吉。|九五：同人，先號咷而後笑，大師克相遇。|上九：同人于郊，無悔。||志同道合|與人和同、公開合作之象。要胸懷開闊、不拘私圈子，才能凝聚人心共同成事；若只結小團體或暗中猜忌就會受阻。", "元亨。|初九：無交害，匪咎，艱則無咎。|九二：大車以載，有攸往，無咎。|九三：公用亨于天子，小人弗克。|九四：匪其彭，無咎。|六五：厥孚交如，威如，吉。|上九：自天祐之，吉無不利。||大有收穫|擁有豐盛、成果盛大之象，是順遂富足的時候。越富有越要謙虛、守誠信、不炫耀，把資源用在正道，才能長保吉祥。", "亨，君子有終。|初六：謙謙君子，用涉大川，吉。|六二：鳴謙，貞吉。|九三：勞謙君子，有終吉。|六四：無不利，撝謙。|六五：不富以其鄰，利用侵伐，無不利。|上六：鳴謙，利用行師，征邑國。||謙虛受益|謙遜低調反而得人心、得助力，是少有的各爻皆吉的卦。多做事少誇耀，保持謙虛，事情會順利並有好結果。", "利建侯行師。|初六：鳴豫，凶。|六二：介于石，不終日，貞吉。|六三：盱豫，悔；遲有悔。|九四：由豫，大有得；勿疑，朋盍簪。|六五：貞疾，恆不死。|上六：冥豫，成有渝，無咎。||安樂預備|和樂愉悅、順應時勢之象，適合行動與籌劃。但不可沉溺享樂、得意忘形，要有所準備與節制，才能長久。", "元亨利貞，無咎。|初九：官有渝，貞吉。出門交有功。|六二：係小子，失丈夫。|六三：係丈夫，失小子。隨有求得，利居貞。|九四：隨有獲，貞凶。有孚在道，以明，何咎？|九五：孚于嘉，吉。|上六：拘係之，乃從維之，王用亨于西山。||順隨時勢|懂得順應時勢、跟隨正確的人與方向。要擇善而從、不盲從；能隨機應變又守住原則，就能得到助力與成果。", "元亨，利涉大川。先甲三日，後甲三日。|初六：幹父之蠱，有子，考無咎，厲終吉。|九二：幹母之蠱，不可貞。|九三：幹父之蠱，小有悔，無大咎。|六四：裕父之蠱，往見吝。|六五：幹父之蠱，用譽。|上九：不事王侯，高尚其事。||整治積弊|事情因長久敷衍而出現弊端，需要整頓革新。要先查明原因再動手處理，行動前後都要謹慎安排，整頓後會重新亨通。", "元亨利貞。至于八月有凶。|初九：咸臨，貞吉。|九二：咸臨，吉，無不利。|六三：甘臨，無攸利。既憂之，無咎。|六四：至臨，無咎。|六五：知臨，大君之宜，吉。|上六：敦臨，吉，無咎。||親臨督導|事業走向上升，有機會接近與領導。以誠懇關懷的態度處理才長久；要居安思危，盛勢之後會有轉弱的時候。", "盥而不薦，有孚顒若。|初六：童觀，小人無咎，君子吝。|六二：闚觀，利女貞。|六三：觀我生，進退。|六四：觀國之光，利用賓于王。|九五：觀我生，君子無咎。|上九：觀其生，君子無咎。||觀察省思|重在觀察與反省：看清環境，也看清自己。不宜急著行動，先以誠敬的態度審視、學習，做出示範讓人信服。", "亨。利用獄。|初九：屨校滅趾，無咎。|六二：噬膚滅鼻，無咎。|六三：噬臘肉，遇毒；小吝，無咎。|九四：噬乾胏，得金矢，利艱貞，吉。|六五：噬乾肉，得黃金，貞厲，無咎。|上九：何校滅耳，凶。||排除阻隔|口中有東西卡住，要咬碎才能合攏，比喻要果斷處理障礙或違規之事。處理問題要公正有力，從小事就矯正，免得惡習累積成大禍。", "亨。小利有攸往。|初九：賁其趾，舍車而徒。|六二：賁其須。|九三：賁如濡如，永貞吉。|六四：賁如皤如，白馬翰如，匪寇婚媾。|六五：賁于丘園，束帛戔戔，吝，終吉。|上九：白賁，無咎。||文飾裝點|重在修飾外表與禮儀，帶來美好與亨通，但只是小有利。外在的美要配合內在實質，最終回歸樸素真誠才是最好。", "不利有攸往。|初六：剝床以足，蔑貞凶。|六二：剝床以辨，蔑貞凶。|六三：剝之，無咎。|六四：剝床以膚，凶。|六五：貫魚，以宮人寵，無不利。|上九：碩果不食，君子得輿，小人剝廬。||剝落衰退|小人勢力增長、局面逐漸被侵蝕，不宜主動出擊。宜安靜等待、保住根本，像留下的大果實不吃掉，待時機自能重新生長。", "亨。出入無疾，朋來無咎。反復其道，七日來復，利有攸往。|初九：不遠復，無祗悔，元吉。|六二：休復，吉。|六三：頻復，厲，無咎。|六四：中行獨復。|六五：敦復，無悔。|上六：迷復，凶，有災眚。用行師，終有大敗，以其國君凶，至于十年不克征。||一陽來復|低谷之後轉機重現，好比冬至一陽初生。及時回到正道、不要走太遠，重新開始會逐漸好轉；執迷不悟、遲遲不改則有災禍。", "元亨利貞。其匪正有眚，不利有攸往。|初九：無妄，往吉。|六二：不耕穫，不菑畬，則利有攸往。|六三：無妄之災，或繫之牛，行人之得，邑人之災。|九四：可貞，無咎。|九五：無妄之疾，勿藥有喜。|上九：無妄，行有眚，無攸利。||守真不妄|不虛妄、不投機，順著自然本分行事就亨通；若懷有不正的心思或強求，反而招災。偶遇意外也要平心處理，不亂用藥亂動作。", "利貞，不家食，吉，利涉大川。|初九：有厲，利已。|九二：輿說輹。|九三：良馬逐，利艱貞。曰閑輿衛，利有攸往。|六四：童牛之牿，元吉。|六五：豶豕之牙，吉。|上九：何天之衢，亨。||大量蓄積|積蓄能力、學識與德行，到一定程度再出來做事。目前宜蓄勢待發、控制衝動，等到暢通無阻時，就會有大的作為。", "貞吉。觀頤，自求口實。|初九：舍爾靈龜，觀我朵頤，凶。|六二：顛頤，拂經于丘頤，征凶。|六三：拂頤，貞凶，十年勿用，無攸利。|六四：顛頤，吉。虎視眈眈，其欲逐逐，無咎。|六五：拂經，居貞吉，不可涉大川。|上九：由頤，厲吉，利涉大川。||頤養自守|與「養」有關：要養身、養德，也要養人。慎言語、節飲食，靠自己正當努力獲取所需，不羨慕他人所有，才能健康吉祥。", "棟橈，利有攸往，亨。|初六：藉用白茅，無咎。|九二：枯楊生稊，老夫得其女妻，無不利。|九三：棟橈，凶。|九四：棟隆，吉；有它吝。|九五：枯楊生華，老婦得其士夫，無咎無譽。|上六：過涉滅頂，凶，無咎。||負擔過重|像樑柱承重過度而彎曲，局面中間過重、兩端太弱。需要非常手段與果斷處置，但要謹慎小心；若硬撐到底可能「滅頂」，要量力而為。", "習坎，有孚，維心亨，行有尚。|初六：習坎，入于坎窞，凶。|九二：坎有險，求小得。|六三：來之坎坎，險且枕，入于坎窞，勿用。|六四：樽酒簋貳，用缶，納約自牖，終無咎。|九五：坎不盈，祗既平，無咎。|上六：係用徽纆，寘于叢棘，三歲不得，凶。||重重險陷|一重又一重的險難，處境艱險。但只要保持誠信、內心堅定，就能在險中前行；不要冒進，一步步小心脫困，求小得而不求大。", "利貞，亨。畜牝牛，吉。|初九：履錯然，敬之，無咎。|六二：黃離，元吉。|九三：日昃之離，不鼓缶而歌，則大耋之嗟，凶。|九四：突如其來如，焚如，死如，棄如。|六五：出涕沱若，戚嗟若，吉。|上九：王用出征，有嘉折首，獲匪其醜，無咎。||光明附麗|如火光明亮、依附正道而發光。要像飼養溫順的牛一樣柔順守正，才能吉祥；火燃得太猛會自焚，行事要節制、珍惜當下。", "亨，利貞，取女吉。|初六：咸其拇。|六二：咸其腓，凶，居吉。|九三：咸其股，執其隨，往吝。|九四：貞吉，悔亡。憧憧往來，朋從爾思。|九五：咸其脢，無悔。|上六：咸其輔頰舌。||真心感應|兩情或人心之間的感應與交流。以真誠無私的心相感才亨通，婚戀事尤其吉；只靠花言巧語或心思亂動，感應就不深。", "亨，無咎，利貞，利有攸往。|初六：浚恆，貞凶，無攸利。|九二：悔亡。|九三：不恆其德，或承之羞，貞吝。|九四：田無禽。|六五：恆其德，貞，婦人吉，夫子凶。|上六：振恆，凶。||持之以恆|貴在長久堅持正道，不輕易改變方向。但「恆」不是死守不變，要能隨時調整；急求深入、搖擺不定、或動輒更張都不利。", "亨，小利貞。|初六：遯尾，厲，勿用有攸往。|六二：執之用黃牛之革，莫之勝說。|九三：係遯，有疾厲，畜臣妾吉。|九四：好遯，君子吉，小人否。|九五：嘉遯，貞吉。|上九：肥遯，無不利。||退避保身|小人漸盛的時候，君子宜適時退讓避開、保存實力。及早從容退出能平安；拖延不走或糾纏其中會有危險，退得好反而有利。", "利貞。|初九：壯于趾，征凶，有孚。|九二：貞吉。|九三：小人用壯，君子用罔，貞厲。羝羊觸藩，羸其角。|九四：貞吉，悔亡。藩決不羸，壯于大輿之輹。|六五：喪羊于易，無悔。|上六：羝羊觸藩，不能退，不能遂，無攸利，艱則吉。||強盛需正|力量強大、氣勢旺盛，但越強越要守正道、有節制。蠻幹像公羊衝撞籬笆會卡住角，靠實力同時守禮守規矩才得吉。", "康侯用錫馬蕃庶，晝日三接。|初六：晉如摧如，貞吉。罔孚，裕無咎。|六二：晉如愁如，貞吉。受茲介福，于其王母。|六三：眾允，悔亡。|九四：晉如鼫鼠，貞厲。|六五：悔亡，失得勿恤，往吉，無不利。|上九：晉其角，維用伐邑，厲吉無咎，貞吝。||上進晉升|像太陽升起，事業、地位逐步上升，得到肯定。要守正、虛心、不貪心；中途受挫也不要急，保持誠信就會有福。", "利艱貞。|初九：明夷于飛，垂其翼。君子于行，三日不食，有攸往，主人有言。|六二：明夷，夷于左股，用拯馬壯，吉。|九三：明夷于南狩，得其大首，不可疾貞。|六四：入于左腹，獲明夷之心，于出門庭。|六五：箕子之明夷，利貞。|上六：不明晦，初登于天，後入于地。||光明受傷|光明被遮蔽、賢者處在不利環境。宜韜光養晦、內明外柔，不鋒芒外露，堅持內心正道，熬過黑暗期後光明會再回來。", "利女貞。|初九：閑有家，悔亡。|六二：無攸遂，在中饋，貞吉。|九三：家人嗃嗃，悔厲吉；婦子嘻嘻，終吝。|六四：富家，大吉。|九五：王假有家，勿恤，吉。|上九：有孚威如，終吉。||齊家有序|講家庭與親近關係的經營。各人守好本分、立好規矩，又有愛與誠信，家就和順；管得太鬆或太嚴都不好，以誠相待最重要。", "小事吉。|初九：悔亡，喪馬勿逐，自復；見惡人，無咎。|九二：遇主于巷，無咎。|六三：見輿曳，其牛掣，其人天且劓，無初有終。|九四：睽孤，遇元夫，交孚，厲無咎。|六五：悔亡，厥宗噬膚，往何咎？|上九：睽孤，見豕負塗，載鬼一車，先張之弧，後說之弧，匪寇婚媾，往遇雨則吉。||乖違背離|彼此意見不合、關係疏離，大事不易成，只宜做小事。求同存異、保持溝通、不要猜疑，真誠相待後誤會往往能化解。", "利西南，不利東北。利見大人，貞吉。|初六：往蹇，來譽。|六二：王臣蹇蹇，匪躬之故。|九三：往蹇，來反。|六四：往蹇，來連。|九五：大蹇，朋來。|上六：往蹇，來碩，吉。利見大人。||險阻難行|前進遇到阻礙，像腳跛行走不便。宜停下來反省、找好助手與貴人，改變方向而不硬闖，在困難中修養自己，終能克服。", "利西南。無所往，其來復吉。有攸往，夙吉。|初六：無咎。|九二：田獲三狐，得黃矢，貞吉。|六三：負且乘，致寇至，貞吝。|九四：解而拇，朋至斯孚。|六五：君子維有解，吉；有孚于小人。|上六：公用射隼于高墉之上，獲之，無不利。||解除困難|困難紓解、緊張消散之象。要趁機把問題處理乾淨，有事早做早吉；不要再糾纏舊事，也要警惕德不配位招來麻煩。", "有孚，元吉，無咎，可貞，利有攸往。曷之用？二簋可用享。|初九：已事遄往，無咎，酌損之。|九二：利貞，征凶，弗損益之。|六三：三人行，則損一人；一人行，則得其友。|六四：損其疾，使遄有喜，無咎。|六五：或益之十朋之龜，弗克違，元吉。|上九：弗損益之，無咎，貞吉，利有攸往，得臣無家。||減損有益|有損才有益，在適當的地方減少、節制，反而帶來真正的收穫。誠心比排場重要，簡單一點也能表達心意，量力而為最好。", "利有攸往，利涉大川。|初九：利用為大作，元吉，無咎。|六二：或益之十朋之龜，弗克違，永貞吉。王用享于帝，吉。|六三：益之用凶事，無咎。有孚中行，告公用圭。|六四：中行，告公從。利用為依遷國。|九五：有孚惠心，勿問元吉。有孚惠我德。|上九：莫益之，或擊之，立心勿恆，凶。||增益受惠|上對下施益、彼此增益的好時機，宜積極進取、做有益大眾的事，得到助力。要持續保持善心；一旦動機轉為只顧自己，好運就會停止。", "揚于王庭，孚號，有厲。告自邑，不利即戎，利有攸往。|初九：壯于前趾，往不勝為咎。|九二：惕號，莫夜有戎，勿恤。|九三：壯于頄，有凶。君子夬夬，獨行遇雨，若濡有慍，無咎。|九四：臀無膚，其行次且。牽羊悔亡，聞言不信。|九五：莧陸夬夬，中行無咎。|上六：無號，終有凶。||果決除弊|要下決心清除小人與弊端，但要公開、有證據、以德服人，不宜以武力硬碰。果斷之中保持警惕與耐心，才不會反遭傷害。", "女壯，勿用取女。|初六：繫于金柅，貞吉，有攸往，見凶，羸豕孚蹢躅。|九二：包有魚，無咎，不利賓。|九三：臀無膚，其行次且，厲，無大咎。|九四：包無魚，起凶。|九五：以杞包瓜，含章，有隕自天。|上九：姤其角，吝，無咎。||不期而遇|意外的相遇或邂逅，來勢突然，要提防一開始看似小的影響逐步壯大。遇到時要保持界線、謹慎處理，不輕易深交。", "亨。王假有廟，利見大人，亨，利貞。用大牲吉，利有攸往。|初六：有孚不終，乃亂乃萃，若號，一握為笑，勿恤，往無咎。|六二：引吉，無咎，孚乃利用禴。|六三：萃如嗟如，無攸利，往無咎，小吝。|九四：大吉，無咎。|九五：萃有位，無咎。匪孚，元永貞，悔亡。|上六：齎咨涕洟，無咎。||聚集匯合|人事物彙聚的時候，需要有共同的目標與好的領導，才能凝聚人心。聚在一起要有防備，以誠信與禮制維持秩序，不然人多反而亂。", "元亨，用見大人，勿恤，南征吉。|初六：允升，大吉。|九二：孚乃利用禴，無咎。|九三：升虛邑。|六四：王用亨于岐山，吉，無咎。|六五：貞吉，升階。|上六：冥升，利于不息之貞。||逐步上升|像樹木生長一樣一步一步向上，事業與地位漸有進展，得到上位者的賞識。穩紮穩打、不躁進，到高處更要自我警醒、持續努力。", "亨，貞，大人吉，無咎。有言不信。|初六：臀困于株木，入于幽谷，三歲不覿。|九二：困于酒食，朱紱方來，利用享祀，征凶，無咎。|六三：困于石，據于蒺藜，入于其宮，不見其妻，凶。|九四：來徐徐，困于金車，吝，有終。|九五：劓刖，困于赤紱，乃徐有說，利用祭祀。|上六：困于葛藟，于臲卼，曰動悔，有悔，征吉。||困窘受限|處境困窘、資源受限，說話也不被相信。此時多說無益，保持信念、靜心修養，以不變的志向度過難關，終能由困轉通。", "改邑不改井，無喪無得，往來井井。汔至亦未繘井，羸其瓶，凶。|初六：井泥不食，舊井無禽。|九二：井谷射鮒，甕敝漏。|九三：井渫不食，為我心惻，可用汲，王明，並受其福。|六四：井甃，無咎。|九五：井冽，寒泉食。|上六：井收勿幕，有孚元吉。||養人不竭|像水井默默滋養眾人而不改常。要持續維護與修整，不能半途而廢；有才能就要被人用，並保持源頭清潔，長久才有好結果。", "己日乃孚，元亨利貞，悔亡。|初九：鞏用黃牛之革。|六二：己日乃革之，征吉，無咎。|九三：征凶，貞厲，革言三就，有孚。|九四：悔亡，有孚改命，吉。|九五：大人虎變，未占有孚。|上六：君子豹變，小人革面，征凶，居貞吉。||變革更新|時機成熟需要改革，但要等人心信服後再行動，不能操之過急。方案要多次商討、有誠信基礎，改革成功後局面煥然一新。", "元吉，亨。|初六：鼎顛趾，利出否，得妾以其子，無咎。|九二：鼎有實，我仇有疾，不我能即，吉。|九三：鼎耳革，其行塞，雉膏不食，方雨虧悔，終吉。|九四：鼎折足，覆公餗，其形渥，凶。|六五：鼎黃耳金鉉，利貞。|上九：鼎玉鉉，大吉，無不利。||鼎新成器|像鼎烹煮食物，象徵新秩序與成就的確立，是大吉亨通。要德才相稱、選對輔助者；若能力不足而承擔過重，鼎足折斷就會翻覆。", "亨。震來虩虩，笑言啞啞。震驚百里，不喪匕鬯。|初九：震來虩虩，後笑言啞啞，吉。|六二：震來厲，億喪貝，躋于九陵，勿逐，七日得。|六三：震蘇蘇，震行無眚。|九四：震遂泥。|六五：震往來厲，億無喪，有事。|上六：震索索，視矍矍，征凶。震不于其躬，于其鄰，無咎，婚媾有言。||雷動驚醒|突然的震動或驚嚇，雖然一時恐懼，卻能促人警醒、修省。保持鎮定、不亂陣腳，事過之後反而笑語平安，也不會丟掉原有的根本。", "艮其背，不獲其身，行其庭，不見其人，無咎。|初六：艮其趾，無咎，利永貞。|六二：艮其腓，不拯其隨，其心不快。|九三：艮其限，列其夤，厲薰心。|六四：艮其身，無咎。|六五：艮其輔，言有序，悔亡。|上九：敦艮，吉。||適時靜止|知止而後安，該停就停。控制慾望與妄動，守住當下，不強行向前；說話、行事都要有分寸，保持心定，才能避免災咎。", "女歸吉，利貞。|初六：鴻漸于干，小子厲，有言，無咎。|六二：鴻漸于磐，飲食衎衎，吉。|九三：鴻漸于陸，夫征不復，婦孕不育，凶。利禦寇。|六四：鴻漸于木，或得其桷，無咎。|九五：鴻漸于陵，婦三歲不孕，終莫之勝，吉。|上九：鴻漸于陸，其羽可用為儀，吉。||循序漸進|像大雁一步一步飛過水邊、岩石、樹木，事情宜按部就班、慢慢推進。如婚嫁般需要等待時機與程序，穩定積累終會有好結果。", "征凶，無攸利。|初九：歸妹以娣，跛能履，征吉。|九二：眇能視，利幽人之貞。|六三：歸妹以須，反歸以娣。|九四：歸妹愆期，遲歸有時。|六五：帝乙歸妹，其君之袂不如其娣之袂良，月幾望，吉。|上六：女承筐無實，士刲羊無血，無攸利。||名分不正|婚嫁或結合中位置、時機不夠正當，不宜急進。若硬要求成，容易有名無實、不得其所；宜守分守禮、耐心等待合適的時機。", "亨，王假之，勿憂，宜日中。|初九：遇其配主，雖旬無咎，往有尚。|六二：豐其蔀，日中見斗，往得疑疾，有孚發若，吉。|九三：豐其沛，日中見沬，折其右肱，無咎。|九四：豐其蔀，日中見斗，遇其夷主，吉。|六五：來章，有慶譽，吉。|上六：豐其屋，蔀其家，闚其戶，闃其無人，三歲不覿，凶。||盛大豐滿|事物達到盛大豐滿，如日正當中。此時宜把握時機、公平照顧各方；但盛極必衰，要有憂患意識，不炫耀、不封閉自己。", "小亨，旅貞吉。|初六：旅瑣瑣，斯其所取災。|六二：旅即次，懷其資，得童僕貞。|九三：旅焚其次，喪其童僕，貞厲。|九四：旅于處，得其資斧，我心不快。|六五：射雉一矢亡，終以譽命。|上九：鳥焚其巢，旅人先笑後號咷。喪牛于易，凶。||客旅在外|像在外作客，處境不穩，只宜小事、低調謹慎。待人要謙和，不要計較瑣碎或高傲；守住財物與人緣，才能平安度過。", "小亨，利有攸往，利見大人。|初六：進退，利武人之貞。|九二：巽在床下，用史巫紛若，吉，無咎。|九三：頻巽，吝。|六四：悔亡，田獲三品。|九五：貞吉，悔亡，無不利。無初有終，先庚三日，後庚三日，吉。|上九：巽在床下，喪其資斧，貞凶。||謙順入微|像風一樣無孔不入，以謙遜柔順的方式滲透、說服，小有亨通。命令要反覆申明、做事要果斷有決心；過度卑屈或猶豫不決都不好。", "亨，利貞。|初九：和兌，吉。|九二：孚兌，吉，悔亡。|六三：來兌，凶。|九四：商兌未寧，介疾有喜。|九五：孚于剝，有厲。|上六：引兌。||喜悅溝通|和悅愉快、能言善道之象，彼此交流讓人開心。要以誠懇和正道為基礎，別一味討好或沉溺享樂，被甜言蜜語引誘就容易出事。", "亨。王假有廟，利涉大川，利貞。|初六：用拯馬壯，吉。|九二：渙奔其機，悔亡。|六三：渙其躬，無悔。|六四：渙其群，元吉。渙有丘，匪夷所思。|九五：渙汗其大號，渙王居，無咎。|上九：渙其血，去逖出，無咎。||化散憂患|把凝結的心結、隔閡或僵局化開，使人心重新聚合。要用共同的信仰或目標來凝聚，放下私心與小團體，散開阻礙後局面更順暢。", "亨。苦節不可貞。|初九：不出戶庭，無咎。|九二：不出門庭，凶。|六三：不節若，則嗟若，無咎。|六四：安節，亨。|九五：甘節，吉，往有尚。|上六：苦節，貞凶，悔亡。||適度節制|凡事要有節制與界線，才能長久亨通。但節制不是苦行，過度壓抑、太苛刻無法持久；要找到舒適而可行的分寸，並選對時機行動。", "豚魚吉，利涉大川，利貞。|初九：虞吉，有它不燕。|九二：鳴鶴在陰，其子和之；我有好爵，吾與爾靡之。|六三：得敵，或鼓或罷，或泣或歌。|六四：月幾望，馬匹亡，無咎。|九五：有孚攣如，無咎。|上九：翰音登于天，貞凶。||誠信感通|內心誠信、虛懷若谷，連小豬與魚都能被感動。待人真誠就能感通彼此、共同克服困難；但光說不做、虛名在外就不會長久。", "亨，利貞。可小事，不可大事。飛鳥遺之音，不宜上，宜下，大吉。|初六：飛鳥以凶。|六二：過其祖，遇其妣；不及其君，遇其臣；無咎。|九三：弗過防之，從或戕之，凶。|九四：無咎，弗過遇之。往厲必戒，勿用永貞。|六五：密雲不雨，自我西郊，公弋取彼在穴。|上六：弗遇過之，飛鳥離之，凶，是謂災眚。||小事可為|小處稍微過一點可以，大事就不宜。做事低調、謙虛、重細節，向下沉穩而不往高處冒進，小事做好就能吉；勉強去做大事會有麻煩。", "亨小，利貞，初吉終亂。|初九：曳其輪，濡其尾，無咎。|六二：婦喪其茀，勿逐，七日得。|九三：高宗伐鬼方，三年克之，小人勿用。|六四：繻有衣袽，終日戒。|九五：東鄰殺牛，不如西鄰之禴祭，實受其福。|上六：濡其首，厲。||事已成功|事情大致完成、各就其位。但盛極而衰，越是成功越要居安思危、持續警惕；一開始吉，放鬆後容易出亂，要保持謹慎、防小漏洞。", "亨，小狐汔濟，濡其尾，無攸利。|初六：濡其尾，吝。|九二：曳其輪，貞吉。|六三：未濟，征凶，利涉大川。|九四：貞吉，悔亡，震用伐鬼方，三年有賞于大國。|六五：貞吉，無悔。君子之光，有孚，吉。|上九：有孚于飲酒，無咎；濡其首，有孚失是。||尚未完成|事情還沒完成、仍有轉機。要看清情勢、不能急躁，像小狐狸過河最怕在終點濕了尾巴。謹慎收尾、穩住節奏，下一個循環就有新機會。"];
const MH_YT=["時機未到，先潛心蓄力，不要妄動。|才能開始顯露，適合出來見貴人、請教前輩。|整天勤奮、夜裡仍警惕反省，雖處危險也能無災。|可以試著進取，也可退回穩守，量力而行就無咎（不會有過失）。|位置與時機最好，大展身手，適合與貴人相見。|爬到頂點過於高亢，物極必反，宜收斂防後悔。", "看到薄霜就知嚴寒將臨，小跡象要及早留意。|正直、端方、廣大，順著本性做事自然沒有不利。|把才華含蓄收藏，守正而不爭功，成果歸於上位。|像把袋口紮緊，少說話、少表態，無咎無譽（沒有過失，也沒有讚譽），謹慎免禍但也無名。|像穿著低調高貴的黃色衣裳，內斂有德，大吉。|陰盛到極點與陽相爭，兩敗俱傷，要避免硬碰。", "起步時徘徊不前，宜守正、先打好基礎並尋找助手。|困難重重、進退兩難；對方不是來搶而是求婚，要耐心等十年才有結果。|沒有嚮導就追鹿入林，貿然行動會吃虧，不如放棄。|看清形勢，主動求援合作，前進吉利。|恩惠被卡住不能廣施，小事可行，大事強推有凶。|走投無路、傷心流淚，要靠求助與反省。", "開始啟蒙需有規矩約束，過度放縱會有困難。|能包容愚昧者並加以引導，吉；善於持家也吉。|見到有錢人就失去自我，這種選擇沒有好處，要保持自主。|困在愚昧中又不肯學習，會有羞吝。|以純真謙虛的態度求教，吉。|對頑固的蒙昧要適度嚴厲糾正，但要防範過度。", "在遠郊等待，還離危險很遠，保持恆心就無災。|等在沙地，有些閒言閒語，最後仍吉。|等在泥濘邊，離險境很近，容易招來外敵，要謹慎。|陷入危險，要設法退出險地，保住安全。|等待時安心飲食休養，守正吉。|進入險境，有意外的三位客人來，恭敬相待終吉。", "不要把爭訟拖長，小有口舌，終究吉。|爭不過就退回，離開避禍，鄉里平安。|靠舊有的德行維持，守正，終吉；為公事不求功。|打不贏就回頭，改變主意安守正道，吉。|由公正者裁斷，是大吉。|即使因爭訟得到賞賜，也很快又被剝奪，不可恃。", "出兵必須有紀律，否則即使贏也是凶。|身在軍中居中指揮，吉無咎（不會有過失），並受上位重賞。|指揮不一，載屍而歸，凶。|暫時退守，不勉強進攻，無咎（不會有過失）。|有可執之理才出手，無咎（不會有過失）；用對的人當統帥，用錯則凶。|論功行賞，小人不可重用。", "以誠信與人親近，無咎（不會有過失），真誠充實終有它吉。|從內部、自己主動誠心親附，守正吉。|親近到不合適的人，要小心。|向外親近賢者，守正吉。|光明正大地親近，不強求，大方自然，吉。|沒有領頭人就想親附，結果凶。", "回到自己的正道，有什麼咎，吉。|被牽引著返回正道，吉。|車輪脫落，夫妻反目，因強行前進而失和。|有誠信，擔憂和血光都能離去，無咎（不會有過失）。|誠信牽連，連鄰居一起富足，要互助。|雨已下、事已成，重德行；此時月近滿，不宜再進。", "以樸素本分的態度前行，往前無咎（不會有過失）。|道路平坦，守正的隱者吉。|能力有限卻硬要逞強，踩到虎尾被咬，凶。|雖踩虎尾但極度謹慎，終吉。|決斷果敢地走，但守正也有危險。|回顧走過的路、檢視吉凶，圓滿大吉。", "拔起茅草連根帶出，與同類一同前進，吉。|包容荒穢、勇於涉險、不遺漏遠方，得到中道的支持。|沒有永遠平坦、沒有只去不返，艱難中守正無咎（不會有過失），享福。|輕鬆地與鄰居往來，不靠財富，也不必告誡就能互信。|君王嫁女、降尊相親，得福大吉。|城牆倒回護城河，泰極轉否，不要再動兵，守正也有憾。", "同類一同進退，守正吉亨。|包容順從，小人吉，大人在閉塞中守住自己亨通。|被迫容忍羞辱之事，處境尷尬。|有上命而行，無咎（不會有過失），同伴也得福。|使閉塞停止，大人吉；要時時警戒，像繫在桑樹根上。|閉塞被推翻，先否後喜。", "在家門口就與人和同，無咎（不會有過失）。|只和同宗親近，格局小，有憾。|埋伏兵於草叢，疑心重，久久不能起事。|爬上城牆卻不攻，知難而退，吉。|先痛哭後歡笑，大軍終能會合。|在遠郊和同，雖不深入也無悔。", "不與害人之事交往，無咎（不會有過失），艱難時小心則無災。|用大車裝載，有能力承擔，前往無咎（不會有過失）。|公侯向天子獻上財物，小人做不到。|不炫耀盛大，無咎（不會有過失）。|以誠信相交又有威嚴，吉。|上天保佑，吉無不利。", "極度謙虛的君子，可以渡過大河，吉。|謙名遠播，守正吉。|有功勞又謙虛，有好結果，吉。|處處發揮謙德，無所不利。|不倚仗財富，可以出兵討伐不服者，無不利。|謙德昭著，可以用兵整頓邑國。", "得意到張揚，凶。|像石頭般堅定，不整天耽於享樂，守正吉。|仰望別人求快樂，後悔；遲疑也後悔。|由你帶來歡樂，大有所得，不要懷疑，朋友會聚合。|長期有隱疾，但不會死，要有節制。|沉迷享樂，若能改變則無咎（不會有過失）。", "職守有變，守正吉；出門與人交往有功。|跟了小的，失去大的，取捨不當。|跟了大的，失去小的，所求可得，宜居守正。|跟隨有收穫，但要守正以防凶；有誠信走在正道，明白何咎。|以誠信嘉美相隨，吉。|被牢牢繫住、長久相隨，如君王在西山祭祀。", "整治父輩留下的弊端，有賢子則無咎（不會有過失），雖危險終吉。|整治母輩弊端，不可太堅持強硬。|整治弊端稍有悔，但沒有大錯。|對弊端寬縱不管，繼續下去會有羞吝。|整治弊端並得到好名聲。|不為王侯做事，高尚其志。", "以感化的方式親臨，守正吉。|感化臨下，吉，無不利。|以甜言蜜語對待，沒有好處；若能憂慮反省則無咎（不會有過失）。|親自到位督導，無咎（不會有過失）。|以智慧領導，這是大君的作法，吉。|以敦厚寬厚面對，吉，無咎（不會有過失）。", "像孩童般淺薄地看，小人無咎（不會有過失），君子會羞吝。|從門縫偷看，視野狹窄，只適合女子守正。|觀察自己的行為，決定進退。|觀察國家的光明，適合受賓禮於王。|審視自己，君子無咎（不會有過失）。|觀察他人影響，君子無咎（不會有過失）。", "腳被刑具套住，小懲而止，無咎（不會有過失）。|咬軟肉很容易，用力過頭到鼻子，無咎（不會有過失）。|咬到陳肉中毒，小有羞吝，無咎（不會有過失）。|咬硬骨肉，得到金箭，艱難守正，吉。|處理難事得到成果，要警惕守正，無咎（不會有過失）。|枷鎖蓋過耳朵，惡積重大，凶。", "把腳裝飾好，捨車步行，寧可實在。|裝飾鬍鬚，外在跟隨內在。|潤澤華美，長久守正吉。|素白無華，白馬奔來，不是搶匪而是求婚。|在丘園儉樸，布帛微薄，雖吝但終吉。|以純白樸素為美，無咎（不會有過失）。", "從床腳開始被侵蝕，根基受損，凶。|侵蝕到床架，更深一步，凶。|在侵蝕中與同類劃清界線，無咎（不會有過失）。|侵蝕到身膚，災禍臨身，凶。|像一串魚依序獲得寵愛，無不利。|大果未被吃掉，君子得車、小人失屋。", "走不遠就回頭，沒有大悔，大吉。|美好地返回，吉。|頻繁反覆回頭，有危險但無咎（不會有過失）。|在眾人中獨自走回正道。|敦厚地返回，無悔。|迷失而不知回頭，凶，有災。", "以真實不妄之心前進，吉。|不為收穫而耕、不為熟田而墾，順勢而行利於前進。|無緣無故的災禍，像牛被人牽走，路人得利、鄰人受災。|可以守正，無咎（不會有過失）。|無妄之病，不用吃藥自然好，有喜。|此時若妄行就有災，無所利。", "有危險，宜停止前進。|車子卸下車軸，暫時停下來蓄力。|好馬追逐，艱難守正，加強防衛則利於前往。|給小牛先上牛角橫木，防患未然，大吉。|閹過的豬牙不傷人，以巧妙方式制止惡，吉。|通往天上大路，通暢亨通。", "捨棄自己的靈龜，只看別人的吃相，凶。|倒過來求養於下，違反常理，前進凶。|違背養的正道，守正也凶，十年不可用。|倒過來求養於下是為了成就善，虎視眈眈需有誠意，無咎（不會有過失）。|違背常規，安居守正則吉，不可涉大川。|靠他來養天下，危險但吉，利於涉大川。", "用白茅墊著祭品，格外小心，無咎（不會有過失）。|枯楊長新芽，老夫娶少妻，無不利。|棟樑彎曲，要垮了，凶。|棟樑隆起堅固，吉；若有其他心思會羞吝。|枯楊開花，老婦嫁壯夫，無咎無譽（沒有過失，也沒有讚譽），不好不壞。|過河沒頂，凶，但出於義所以無咎（不會有過失）。", "陷入坎中又陷更深，凶。|身處險中，只求小的收穫。|來去都是險，前進後退都險，不要行動。|一樽酒兩碗飯，簡單真誠，從窗口進獻，終無咎（不會有過失）。|坎還未滿，只要平復就無咎（不會有過失）。|被繩索綑綁、置於荊棘，三年不得脫身，凶。", "腳步雜亂，敬慎對待，無咎（不會有過失）。|黃色的光明，居中得正，大吉。|夕陽西下，不擊缶唱歌就會嘆老，凶。|突然來臨像火焚燒，被拋棄，過度急躁。|淚流滿面、憂傷嘆息，反而吉。|君王出征，有好成果，斬首領、不株連，無咎（不會有過失）。", "感應在腳拇指，才剛開始，感動很小。|感應在小腿，一動就凶，安居則吉。|感應在大腿，總是隨別人動，前進有羞吝。|守正吉；心思不定來來去去，只有朋友順從你的想法。|感應在背肉，不再有所動，無悔。|感應只停在口舌上，只是說說而已。", "一開始就想深入長久，守正也凶，無所利。|悔恨消失。|德行不能持久，會招來羞辱。|打獵沒有獵物，所求不得。|保持德行，婦人吉，男子凶。|總是動盪不定，凶。", "退避落在最後，危險，不宜前往。|用黃牛皮牢牢綁住，沒人能解開（堅定守住）。|被牽絆而難退，有病有危險；養臣妾吉。|愉快地隱退，君子吉，小人不行。|美好地退隱，守正吉。|從容寬裕地退隱，無不利。", "只在腳趾逞強，前進凶，確定有誠信。|守正吉。|小人逞勇，君子不用，守正也危險；像羊撞籬笆被卡住角。|守正吉，籬笆破開，車軸強壯。|在田埂上輕易丟了羊，無悔。|公羊撞籬笆，進退不得，無所利；艱難守住則吉。", "前進被挫折，守正吉；不被信任也要寬裕處之，無咎（不會有過失）。|前進而憂愁，守正吉，受到祖母般的大福。|大家認可，悔恨消失。|像貪婪的大老鼠，守正也危險。|悔恨消失，得失不用計較，前往吉。|進到牛角尖，只可用來攻伐自己的領邑，危險但吉，無咎（不會有過失）。", "光明受傷而飛，垂下翅膀；君子奔走三天沒飯吃，主人有閒話。|傷到左腿，用強壯的馬拯救，吉。|向南方狩獵，捉到首領，不可急於守正。|深入內情，抓到明夷之心，走出門庭。|像箕子在黑暗中守正，利守正。|不明而昏暗，起先登天，後來落入地。", "在家中先立規矩，悔恨消失。|不專擅，在家管飲食，守正吉。|家人嚴厲時雖後悔卻吉；嬉笑無度反而終吝。|使家富裕，大吉。|君王以德感化家庭，不用憂慮，吉。|有誠信又有威嚴，終吉。", "悔恨消失，丟了馬別追，自然回來；見到惡人也無咎（不會有過失）。|在巷子中巧遇主人，無咎（不會有過失）。|看到車被拖、牛被拉，人受刑，起先不好，後來有好結果。|背離而孤獨，遇到好夥伴，相互誠信，雖危無咎（不會有過失）。|悔恨消失，宗親咬膚（親近），前進何咎。|背離孤立，見到髒豬、鬼怪滿車，先拉弓後放下，不是強盜是來求婚，遇雨則吉。", "前進有困難，回來反得讚譽。|王臣一再遇到困難，不是為自己的緣故。|前進有困難，回頭反而回到原位。|前進有困難，回來與人連結合力。|大難臨頭，朋友來幫忙。|前進有困難，回來有大收穫，吉；利於見大人。", "難解之初，沒有災咎。|狩獵得三隻狐狸，得到黃色箭，守正吉。|背著東西又坐車，招來盜賊，守正也羞吝。|解開你的拇指（脫離小人），朋友就來誠信相待。|君子能解開困難，吉，對小人有誠信。|公侯射下高牆上的鷹，獲得，無不利。", "事完了就趕快去幫助，無咎（不會有過失），要斟酌減損。|守正有利，前進有凶；不減損自己而增益他人。|三個人走會損失一個，一個人走則得朋友。|減少疾病，快速恢復有喜，無咎（不會有過失）。|有人送你十朋大龜，無法拒絕，大吉。|不損失自己也能增益別人，無咎（不會有過失），守正吉，有臣而無私家。", "利於大興作為，大吉，無咎（不會有過失）。|有人送你貴重大龜，不能違抗，長久守正吉；君王祭天吉。|在凶險之事上得益，無咎（不會有過失）；有誠信走中道，持圭告公。|走中道稟告公侯並獲聽從，利於依託遷國。|有誠信、惠及人心，不用問，大吉。|沒有人幫助，反而有人攻擊，立心不能恆久，凶。", "腳趾逞強，前進不能獲勝反成過失。|警惕呼號，夜間有敵兵，不用憂慮。|顴骨露出怒氣，有凶；君子果斷獨行，遇雨沾濕有怒，無咎（不會有過失）。|臀部沒有皮，行走遲疑；牽羊則悔亡，但聽了話不相信。|像剷除莧陸草（小人）般果決，合乎中道則無過。|不用再號呼，最終有凶。", "用金屬制動器拴住，守正吉；前進有凶，像瘦豬躁動。|廚房有魚，無咎（不會有過失），但不利於賓客。|臀部沒有皮，行走遲疑，危險，沒有大過失。|廚房沒有魚，起而爭則凶。|用杞柳包瓜，內含美德，自天而降。|在角落相遇，有羞吝，無咎（不會有過失）。", "誠信不能持久，心亂心聚，呼號求助，一握手破涕為笑，無咎（不會有過失）。|被引領聚合吉，無咎（不會有過失），有誠信才適合簡單祭祀。|聚而嘆息，無所利，前往無咎（不會有過失），小有羞吝。|聚集大吉，無咎（不會有過失）。|聚集有位，無咎（不會有過失）；不被信任要長久守正，悔恨消失。|嘆息流淚，無咎（不會有過失）。", "獲得信任而上升，大吉。|有誠信，簡單祭祀也可，無咎（不會有過失）。|上升進入空城，沒有阻礙。|君王在岐山祭祀，吉，無咎（不會有過失）。|守正吉，一階一階上升。|昏昧中仍想上升，利於持續守正不息。", "屁股困在樹墩上，進入幽谷，三年不見人。|被酒食困住，紅袍加身的人將來，利於祭祀，前進凶，無咎（不會有過失）。|困在石頭上，坐在蒺藜上，回到家看不到妻子，凶。|來得緩慢，困在金車中，羞吝，終究有結果。|受刑傷害，困於紅袍的人，慢慢有喜悅，利於祭祀。|困在藤蔓和不穩處，說動就後悔，有悔但前進吉。", "井底有泥不能喝，舊井沒有禽鳥來。|井水只養小魚，瓦罐破漏。|井已疏通卻沒人喝，令人心痛；若君王明智則共享福氣。|修砌井壁，無咎（不會有過失）。|井水清冽，喝寒泉。|取水後不要蓋住，有誠信，大吉。", "用黃牛皮牢牢綁住，不宜變動。|時機到了才改革，前進吉，無咎（不會有過失）。|貿然前進凶，守正也危險；改革的話要多次討論，才有誠信。|悔恨消失，有誠信、改變天命，吉。|大人像老虎般變化，不用占卜就已有誠信。|君子像豹般變化，小人只改面貌；前進凶，安居守正吉。", "鼎倒過來，利於倒出污穢，得妾生子，無咎（不會有過失）。|鼎中有食物，我的仇人有病，不能靠近我，吉。|鼎耳壞了，行不通，美味不能吃，將下雨減少悔恨，終吉。|鼎腳折斷，打翻美食，弄髒，凶。|黃色鼎耳配金鉉，利守正。|玉製鼎鉉，大吉，無不利。", "雷來恐懼，之後笑語連連，吉。|雷來有危險，丟了很多錢財，登上高丘避難，不用追，七日自得。|驚雷讓人恍惚，若因此行動改正則無災。|雷擊陷入泥中，震動消失。|雷來去都危險，無大損失，有事要做。|雷嚇得發抖、眼神驚恐，前進凶；災不在自己而在鄰居，無咎（不會有過失）。", "止於腳趾，一開始就停住，無咎（不會有過失），利於長久守正。|止於小腿，不能救助跟隨者，心裡不痛快。|止在腰間，裂開脊肉，危險焦慮攻心。|止於全身，無咎（不會有過失）。|止於口，言語有條理，悔恨消失。|敦厚地知止，吉。", "大雁漸進到水邊，小孩有危險，有閒話，無咎（不會有過失）。|漸進到大石上，飲食快樂，吉。|漸進到陸地，丈夫出征不回，婦人懷孕不養，凶；利於防禦盜寇。|漸進到樹上，或許找到平穩樹枝，無咎（不會有過失）。|漸進到丘陵，婦人三年不孕，終究無人能勝，吉。|漸進到高處，羽毛可用作儀飾，吉。", "嫁妹作陪嫁，跛腳也能走，前進吉。|瞎眼也能看，利於幽靜守正。|等待機會才出嫁，反成陪嫁。|嫁期延誤，遲嫁也有時機。|帝乙嫁女，正妻衣袖不如陪嫁的好，月近滿，吉。|女子捧筐無實物，男子刺羊不見血，無所利。", "遇到相配的主人，即使地位均等也無過，前往受尊崇。|遮蔽豐盛，日中見到北斗，前進會被懷疑；以誠信啟發則吉。|幔帳遮暗，日中見小星，折斷右臂，無咎（不會有過失）。|遮蔽太盛，日中見北斗，遇到平等的主人，吉。|招來有文采的人才，有慶賀與讚譽，吉。|把屋子造得很大，卻遮住家，窺看無人，三年不見，凶。", "旅途中斤斤計較，自招災禍。|旅途有住處，帶著錢財，得到忠僕。|旅舍被燒，失去僕人，守正也危險。|旅途暫居，得到資產與斧，我心不快。|射野雞失去一支箭，最終得到美名與任命。|鳥巢被燒，旅人先笑後哭，在田界上丟牛，凶。", "猶豫進退，利於武人堅定守正。|謙卑到床下，用祝史巫覡紛紛祈禱，吉，無咎（不會有過失）。|頻繁地屈從，有羞吝。|悔恨消失，打獵得三種獵物。|守正吉，悔恨消失，無不利；起初不好後來有好結果，吉。|謙卑到床下，失去資產與斧，守正凶。", "和悅相處，吉。|以誠信喜悅，吉，悔恨消失。|來求取喜悅（討好），凶。|商討喜悅還不安定，隔絕疾病就有喜。|信任剝蝕之人，有危險。|被引誘去喜悅。", "用強壯的馬來救助，吉。|渙散時奔向可依靠的桌几，悔恨消失。|散去自身私欲，無悔。|化散小團體，大吉；散聚成丘，是常人想不到的。|如汗水般發布大號令，散出王倉積蓄，無過。|化散憂傷，遠離危險，無咎（不會有過失）。", "不出門庭，無咎（不會有過失）。|該出門卻不出，凶。|不節制就會嘆息，無咎（不會有過失）（自作自受）。|安然地節制，亨通。|以愉快的心節制，吉，前進受尊重。|過分苦行的節制，守正凶，悔恨消失。", "安守等待吉，若有他心就不安。|鶴在樹蔭鳴叫，小鶴唱和；我有美酒，願與你共享。|遇到對手，有時擊鼓進攻，有時罷兵，有時哭泣有時歌唱。|月近滿，馬匹走失，無咎（不會有過失）。|誠信牽繫不斷，無咎（不會有過失）。|雞鳴聲想上天，守正凶。", "像鳥一直往高處飛，凶。|越過祖父遇到祖母；不到君主那裡，遇到臣下，無咎（不會有過失）。|不夠防備，小人會害你，凶。|沒有過錯，不要太過，遇到要警戒，不要長久守舊。|烏雲密佈不下雨，自西郊來，公侯射得穴中獵物。|太過頭而錯過，鳥離去，凶，這是災禍。", "拖住車輪、濕了尾巴，無咎（不會有過失）。|婦人丟了車簾，不用追，七日自得。|高宗討伐鬼方，三年才打下，小人不可用。|華美的衣服要預備破布（防漏水），終日戒備。|東鄰殺牛祭祀，不如西鄰簡單祭祀，實際得福。|弄濕了頭，危險。", "弄濕了尾巴，羞吝。|拖住車輪，守正吉。|尚未完成，前進凶；利於涉大川。|守正吉，悔恨消失，奮力討伐鬼方，三年後得賞。|守正吉，無悔，君子光明，有誠信，吉。|安然飲酒有誠信，無咎（不會有過失）；若弄濕頭，就失去正道。"];
const MH_TN={乾:1,兌:2,離:3,震:4,巽:5,坎:6,艮:7,坤:8};
