const mhKw=(u,l)=>MH_KW[MH_TN[l]-1][MH_TN[u]-1];
const mhNow=()=>{const d=new Date(),p=n=>String(n).padStart(2,'0');return d.getFullYear()+'-'+p(d.getMonth()+1)+'-'+p(d.getDate())+'T'+p(d.getHours())+':'+p(d.getMinutes())};
const MH_ZHI='子丑寅卯辰巳午未申酉戌亥',MH_GAN='甲乙丙丁戊己庚辛壬癸',MH_YAO=['初爻','二爻','三爻','四爻','五爻','上爻'];
let mhOpen=false,mhTab='num',mhN1='',mhN2='',mhT='',mhQ='',mhNote='',mhSeason='auto',mhRes=null,mhResBy={};
let mhUndo=null;
const mhSnap=()=>({n1:mhN1,n2:mhN2,t:mhT,q:mhQ,note:mhNote,se:mhSeason,res:mhRes,by:Object.assign({},mhResBy)});
function mhClear(){mhUndo=null;mhN1='';mhN2='';mhT=mhNow();mhQ='';mhNote='';mhSeason='auto';mhRes=null;mhResBy={}}
function mhLunar(d){try{const p=new Intl.DateTimeFormat('en-u-ca-chinese',{year:'numeric',month:'numeric',day:'numeric'}).formatToParts(d),g=t=>(p.find(x=>x.type===t)||{}).value||'',m=g('month'),mo=parseInt(m,10),da=parseInt(g('day'),10),y=parseInt(g('relatedYear'),10);if(!(mo>=1&&mo<=12&&da>=1&&y))return null;return{y,m:mo,d:da,leap:/bis/i.test(m)}}catch(e){return null}}
const mhSeasonOf=m=>m<=3?'春':m<=6?'夏':m<=9?'秋':'冬';
const mhFmt=d=>d.getFullYear()+'/'+String(d.getMonth()+1).padStart(2,'0')+'/'+String(d.getDate()).padStart(2,'0')+' '+String(d.getHours()).padStart(2,'0')+':'+String(d.getMinutes()).padStart(2,'0');
function mhGo(){let r,meta;const sel=mhSeason;
  try{
    if(mhTab==='num'){const a=mhN1.trim(),b=mhN2.trim();if(!/^\d+$/.test(a)||!/^\d+$/.test(b)){toast('請輸入兩組正整數');return}
      const n1=Number(a),n2=Number(b);if(!Number.isSafeInteger(n1)||!Safe(n2)||n1<=0||n2<=0){toast('數字必須是正整數，且不可過大');return}
      const now=new Date(),L=mhLunar(now),season=sel==='auto'?(L?mhSeasonOf(L.m):null):sel;
      r=MH.castHexagram(n1,n2,{season});meta={mode:'num',n1,n2,t:now.getTime(),season,auto:sel==='auto',lm:L?L.m:null}}
    else{const t=mhT?new Date(mhT):new Date();if(isNaN(t.getTime())){toast('起卦時間格式不正確');return}
      const h=t.getHours(),Ls=new Date(t.getTime());if(h===23)Ls.setDate(Ls.getDate()+1);const L=mhLunar(Ls);if(!L){toast('這個瀏覽器無法換算農曆');return}
      const yi=((L.y-4)%12+12)%12,yz=yi+1,hz=Math.floor(((h+1)%24)/2)+1,sum=yz+L.m+L.d,season=sel==='auto'?mhSeasonOf(L.m):sel;
      r=MH.castHexagram(sum,sum+hz,{season,movingTotal:sum+hz});
      meta={mode:'time',t:t.getTime(),season,auto:sel==='auto',lm:L.m,time:mhFmt(t),ly:MH_GAN[((L.y-4)%10+10)%10]+MH_ZHI[yi],lmon:(L.leap?'閏':'')+L.m,ld:L.d,yz,hz,zy:MH_ZHI[yi],zh:MH_ZHI[hz-1],sum}}
  }catch(e){toast('排盤失敗：'+String(e&&e.message||e).slice(0,40));return}
  mhRes={id:uid(),t:Date.now(),meta,r};render();const el=$('#mhres');if(el)el.scrollIntoView({block:'start',behavior:'smooth'})}
const Safe=Number.isSafeInteger;
function mhSvg(lines,mark){let h='<svg viewBox="0 0 100 100" width="46" height="46" aria-hidden="true">';for(let i=0;i<6;i++){const y=(5-i)*17+2,c=(i+1===mark)?'#d98faa':'currentColor';if(lines[i])h+='<rect x="0" y="'+y+'" width="100" height="11" rx="2" fill="'+c+'"/>';else h+='<rect x="0" y="'+y+'" width="40" height="11" rx="2" fill="'+c+'"/><rect x="60" y="'+y+'" width="40" height="11" rx="2" fill="'+c+'"/>'}return h+'</svg>'}
function mhGuaBlock(lab,name,u,l,mark,mlab,isBen){const kw=mhKw(u,l),f=(MH_TXT[kw-1]||'').split('|'),yao=f.slice(1,7),ex=f[7],gl=t=>'<span style="color:var(--soft)">'+t+'</span>';
  return '<div style="margin:0 0 12px;padding:10px 12px;border:1.2px var(--bs,dashed) var(--line);border-radius:12px"><b style="font-weight:500">'+lab+'：'+esc(name)+'（第'+kw+'卦）· 卦意：'+esc(f[8])+'</b>'
   +'<div style="margin-top:6px">'+gl('卦辭')+'　'+esc(f[0])+'</div>'
   +'<div style="margin-top:6px">'+gl('爻辭')+[5,4,3,2,1,0].map(i=>'<div'+((i+1===mark)?' style="color:#c0607f;font-weight:500"':'')+'>'+esc(yao[i])+((i+1===mark)?'　◀ '+mlab:'')+'</div>').join('')+(ex?'<div>'+esc(ex)+'</div>':'')+'</div>'
   +'<div style="margin-top:6px">'+gl(isBen?'卦辭白話':'白話')+'　'+esc(f[9])+'</div>'+((isBen&&mark)?'<div style="margin-top:6px">'+gl('動爻白話（'+MH_YAO[mark-1]+'）')+'　'+esc((MH_YT[kw-1]||'').split('|')[mark-1]||'')+'</div>':'')+'</div>'}
function mhResultHtml(rec){const r=rec.r,m=rec.meta,mv=r.movingLine,o=r.originalLines,hl=[o[1],o[2],o[3],o[2],o[3],o[4]],sg=n=>(n>0?'+':'')+n;
  const col=(lab,lines,name,u,l,ue,le,mark)=>'<div style="flex:1;min-width:0;text-align:center"><div class="hint" style="margin:0 0 4px">'+lab+'</div><div style="display:flex;justify-content:center;color:var(--ink)">'+mhSvg(lines,mark)+'</div><div style="font-weight:500;margin-top:4px;font-size:calc(14px*var(--fz,1))">'+esc(name)+'</div><div class="hint" style="margin:2px 0 0">第'+mhKw(u,l)+'卦</div><div class="hint" style="margin:0">上'+u+'（'+ue+'）</div><div class="hint" style="margin:0">下'+l+'（'+le+'）</div></div>';
  const row=(k,v)=>'<div style="margin:0 0 9px"><b style="font-weight:500">'+k+'</b><br><span style="color:var(--soft)">'+v+'</span></div>';
  const rem=n=>'餘 '+n+(n===0?'（取 8）':''),rem6=n=>'餘 '+n+(n===0?'（取 6）':'');
  const c=r.calculation;
  const qline=(rec.q?'<div style="margin:0 0 10px;font-size:calc(14px*var(--fz,1))"><span style="color:var(--soft)">所問之事</span>　'+esc(rec.q)+'</div>':'')+(rec.note?'<div style="margin:0 0 10px;font-size:calc(14px*var(--fz,1))"><span style="color:var(--soft)">備注</span>　'+esc(rec.note)+'</div>':'');const head=m.mode==='num'?'報數排盤：數字一 '+m.n1+'、數字二 '+m.n2:'時間排盤：'+m.time+'（農曆'+m.ly+'年'+m.lmon+'月'+m.ld+'日 '+m.zh+'時）';
  const how=m.mode==='num'?('數字一 '+m.n1+' ÷ 8 '+rem(c.upperRemainder)+' → 上卦「'+r.upperGua+'」；數字二 '+m.n2+' ÷ 8 '+rem(c.lowerRemainder)+' → 下卦「'+r.lowerGua+'」；兩數之和 '+c.sum+' ÷ 6 '+rem6(c.movingLineRemainder)+' → 動爻在'+MH_YAO[mv-1]+'。')
    :('年支 '+m.zy+'（'+m.yz+'）＋農曆月 '+(m.lmon.replace('閏',''))+'＋農曆日 '+m.ld+' ＝ '+m.sum+'，÷ 8 '+rem(c.upperRemainder)+' → 上卦「'+r.upperGua+'」；再加時支 '+m.zh+'（'+m.hz+'）＝ '+c.movingTotal+'，÷ 8 '+rem(c.lowerRemainder)+' → 下卦「'+r.lowerGua+'」；'+c.movingTotal+' ÷ 6 '+rem6(c.movingLineRemainder)+' → 動爻在'+MH_YAO[mv-1]+'。');
  const seasonTxt=m.season?(m.season+'季（'+(m.auto?'自動，依農曆'+m.lm+'月推算':'手動選擇')+'）'):'未提供（無法取得農曆月份，不判斷旺衰）';
  const strength=m.season?(r.bodyStrength.description+' '+r.useStrength.description+'<br>'+r.strengthAdjustment.description):'未提供季節，不做旺衰調整。';
  const sc=r.score;
  return qline+'<div class="hint" style="margin:0 0 10px">'+esc(head)+'</div>'
   +'<div style="display:flex;gap:6px;margin-bottom:12px">'+col('本卦',o,r.benGua,r.upperGua,r.lowerGua,r.upperElement,r.lowerElement,mv)+col('互卦',hl,r.huGua,r.huUpperGua,r.huLowerGua,r.huUpperElement,r.huLowerElement,0)+col('變卦',r.changedLines,r.bianGua,r.bianUpperGua,r.bianLowerGua,r.bianUpperElement,r.bianLowerElement,0)+'</div>'
   +'<div style="font-size:calc(14px*var(--fz,1));line-height:1.8">'
   +row('起卦',esc(how))
   +row('體用','體卦：'+esc(r.bodyGua)+'（'+r.bodySide+'，'+r.bodyElement+'）　用卦：'+esc(r.useGua)+'（'+r.useSide+'，'+r.useElement+'）<br>'+esc(r.relationType)+'：'+esc(r.relationDescription))
   +row('季節旺衰','季節：'+esc(seasonTxt)+'<br>'+esc(strength).replace(/&lt;br&gt;/g,'<br>'))
   +row('變卦影響',esc(r.changeEffect.description))
   +row('互卦影響',esc(r.huEffect.description))
   +row('變卦趨勢',esc(r.trend.description))
   +'<div style="margin:0 0 6px"><b style="font-weight:500">綜合：'+esc(r.overall.level)+'（總分 '+sg(sc.total)+'）</b><br><span style="color:var(--soft)">'+esc(r.overall.description)+'<br>體用 '+sg(sc.relation)+'　變卦 '+sg(sc.change)+'　互卦 '+sg(sc.hu)+'　旺衰 '+sg(sc.strengthAdjustment)+'</span></div>'
   +'<div style="margin:14px 0 6px"><b style="font-weight:500">卦辭、爻辭與白話解釋</b></div>'
   +mhGuaBlock('本卦',r.benGua,r.upperGua,r.lowerGua,mv,'動爻',1)+mhGuaBlock('互卦',r.huGua,r.huUpperGua,r.huLowerGua,0,'')+mhGuaBlock('變卦',r.bianGua,r.bianUpperGua,r.bianLowerGua,0,'')
   +'<p class="hint" style="margin:8px 0 0">卦辭、爻辭為《周易》原文，白話為概括性說明。梅花易數流派不同，這是依固定規則計算的參考結果，不代表唯一解法。</p></div>'}
function vMh(){
  const head='<div class="ph2"><button class="ib" data-a="mhback">‹</button><h1>梅花易數</h1></div>';
  const tabs='<div class="stabs" style="margin:-4px 0 10px">'+[['num','報數排盤'],['time','時間排盤']].map(([k,n])=>'<button class="stab '+(mhTab===k?'on':'')+'" style="flex:1" data-a="mhtab" data-i="'+k+'">'+n+'</button>').join('')+'</div>';
  const seg='<div class="sr" style="margin-top:16px"><span>季節</span></div><div class="seg" style="margin-top:6px">'+[['auto','自動'],['春','春'],['夏','夏'],['秋','秋'],['冬','冬']].map(([k,n])=>'<button class="'+(mhSeason===k?'on':'')+'" data-a="mhs" data-i="'+k+'">'+n+'</button>').join('')+'</div><p class="hint" style="margin:6px 2px 0">如沒選擇季節則自動依農曆月份推算（1–3 春、4–6 夏、7–9 秋、10–12 冬）</p>';
  const btns='<div style="display:flex;gap:10px;margin-top:8px"><div style="flex:1;display:flex;gap:6px"><button class="btn" style="flex:1;margin:0;padding-left:4px;padding-right:4px;white-space:nowrap'+(mhUndo?'':';opacity:.45')+'" data-a="mhundo">退回重置</button><button class="btn" style="flex:1;margin:0;padding-left:4px;padding-right:4px" data-a="mhreset">重置</button></div><button class="btn s" style="flex:1;margin:0" data-a="mhgo">立即排盤</button></div><textarea class="mh-in" id="mhq" rows="1" placeholder="所問之事（選填）" style="margin-top:14px;resize:none;line-height:1.6;height:48px;min-height:48px;overflow:hidden;display:block">'+esc(mhQ)+'</textarea><textarea class="mh-in" id="mhnote" rows="2" placeholder="備注（選填）" style="margin-top:10px;resize:none;line-height:1.6;height:76px;min-height:76px;overflow:auto;display:block">'+esc(mhNote)+'</textarea><div style="display:flex;gap:10px;margin-top:10px"><button class="btn" style="flex:1;margin:0" data-a="mhcopy">複製問題與答案</button><button class="btn" style="flex:1;margin:0" data-a="mhsave">保存紀錄</button></div>';
  const body=mhTab==='num'
    ?'<div style="display:grid;grid-template-columns:1fr 1fr;gap:10px"><input class="mh-in" id="mh1" type="text" inputmode="numeric" pattern="[0-9]*" autocomplete="off" placeholder="數字一" value="'+esc(mhN1)+'"><input class="mh-in" id="mh2" type="text" inputmode="numeric" pattern="[0-9]*" autocomplete="off" placeholder="數字二" value="'+esc(mhN2)+'"></div><p class="hint" style="margin:6px 2px 0">輸入兩個正整數：數字一起上卦、數字二起下卦，兩數之和定動爻。每組最多 15 位數。</p>'
    :'<div class="sr"><span>起卦時間</span></div><input class="mh-in" id="mht" type="datetime-local" value="'+esc(mhT)+'" style="margin-top:6px"><p class="hint" style="margin:6px 2px 0">預設為進入此頁時的時間，可自行修改；清空則使用按下「立即排盤」當下的時間。以年支＋農曆月＋農曆日起上卦，再加時支起下卦與動爻；23 點起算子時，農曆日期以次日計。</p>';
  return head+tabs+'<div class="card" style="margin-top:12px">'+body+seg+btns+'</div>'+(mhRes?'<div class="card" id="mhres" style="margin-top:12px">'+mhResultHtml(mhRes)+'</div>':'')}